function Collect(uint _am)
public
payable
{
    if(balances[msg.sender]>MinSum && balances[msg.sender]>=_am)
    {

        balances[msg.sender] = (balances[msg.sender] - _am);
        (bool _veri_ok,) = msg.sender.call{value: _am}("");
        if(_veri_ok)
        {

            Log.AddMessage(msg.sender,_am,"Collect");
        } else {revert (); }
    }
}
